// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount, address target, bytes calldata data) public {
        vm.assume(target != address(this));
        // fund the contract directly with a fuzzed amount; no value is sent with Command
        uint256 amt = bound(amount, 1 wei, type(uint256).max / 2);
        vm.deal(address(c), amt);

        // owner (test contract) calls Command forwarding ZERO value
        vm.prank(address(this));
        (bool ok, ) = address(c).call{value: 0}(
            abi.encodeWithSignature("Command(address,bytes)", target, data)
        );

        // Rule: a zero-value Command (to any recipient that accepts funds)
        // must succeed AND leave the contract's entire balance untouched.
        assertTrue(ok && address(c).balance == amt);
    }
}
